func TestStoreStubBenchModeZeroAlloc(t *testing.T) {
	s := storetest.NewStoreStub(nil, storetest.StoreStubBenchMode())
	s.OnDelete.Returns(nil)
	s.OnGet.Returns("", nil)
	s.OnPut.Returns(nil)

	t.Run("Delete", func(t *testing.T) {
		const iterations = 100
		avgAllocs := testing.AllocsPerRun(iterations, func() {
			_ = s.Delete(t.Context(), "")
		})
		testkit.Equal(t, int(avgAllocs), 0, "Delete in BenchMode must be 0 alloc")
	})

	t.Run("Get", func(t *testing.T) {
		const iterations = 100
		avgAllocs := testing.AllocsPerRun(iterations, func() {
			_, _ = s.Get(t.Context(), "")
		})
		testkit.Equal(t, int(avgAllocs), 0, "Get in BenchMode must be 0 alloc")
	})

	t.Run("Put", func(t *testing.T) {
		const iterations = 100
		avgAllocs := testing.AllocsPerRun(iterations, func() {
			_ = s.Put(t.Context(), "", "")
		})
		testkit.Equal(t, int(avgAllocs), 0, "Put in BenchMode must be 0 alloc")
	})

}
